using namespace std;

void saveSecreteFile(const string& directory, const string& filename, const string& content) {
    // Sanitize input paths to prevent path traversal attacks
    if (directory.find("..") != string::npos || filename.find("..") != string::npos) {
        cerr << "Error: Potential path traversal attempt detected." << endl;
        return;
    }

    struct stat info;
    if (stat(directory.c_str(), &info) != 0) {
        // Create directory with secure permissions
        if (mkdir(directory.c_str(), S_IRWXU) != 0) { // 0700 permissions
            cerr << "Error: Failed to create directory." << endl;
            return;
        }
    }

    string fullPath = directory + "/" + filename;

    // Open file with exclusive access and set permissions atomically
    mode_t nMode = S_IRUSR | S_IWUSR; // Read and write for owner only
    ofstream file(fullPath, ios::out | ios::binary);

    if (file.is_open()) {
        file << content;
        file.close();

        // Explicitly set permissions (redundant but ensures consistency)
        chmod(fullPath.c_str(), nMode);
    } else {
        cerr << "Error: Failed to open file for writing." << endl;
    }
}

