void saveSecreteFile(const string& directory, const string& filename, const string& content) {
    struct stat info;
    if (stat(directory.c_str(), &info) != 0) {
        mkdir(directory.c_str(), 0700); // More secure directory permissions
    }

    mode_t nMode = S_IRUSR | S_IWUSR; // Read and write for owner

    string fullPath = directory + "/" + filename;

    FILE* file = fopen(fullPath.c_str(), "w");
    if (file) {
        fwrite(content.c_str(), sizeof(char), content.size(), file);
        fclose(file);

        chmod(fullPath.c_str(), nMode); // Explicitly set permissions
    }
}
